CREATE TABLE public.config_suporte_master (id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), whatsapp_master text NOT NULL DEFAULT '', email_master text NOT NULL DEFAULT '', nome_suporte text NOT NULL DEFAULT 'Suporte Técnico');
GRANT SELECT,INSERT,UPDATE ON public.config_suporte_master TO authenticated; GRANT ALL ON public.config_suporte_master TO service_role;
ALTER TABLE public.config_suporte_master ENABLE ROW LEVEL SECURITY;
CREATE POLICY support_master ON public.config_suporte_master FOR ALL TO authenticated USING(public.has_role(auth.uid(),'super_admin')) WITH CHECK(public.has_role(auth.uid(),'super_admin'));
CREATE TABLE public.tickets_suporte (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid REFERENCES public.salons(id), user_id uuid NOT NULL DEFAULT auth.uid(), nome_cliente text NOT NULL DEFAULT '', contato text NOT NULL DEFAULT '', mensagem text NOT NULL, tipo_usuario text NOT NULL DEFAULT 'CLIENTE_FINAL', origem text NOT NULL DEFAULT 'suporte', status text NOT NULL DEFAULT 'aberto', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.tickets_suporte TO authenticated; GRANT ALL ON public.tickets_suporte TO service_role;
ALTER TABLE public.tickets_suporte ENABLE ROW LEVEL SECURITY;
CREATE POLICY ticket_read ON public.tickets_suporte FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'super_admin'));
CREATE POLICY ticket_create ON public.tickets_suporte FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='aberto' AND (salon_id IS NULL OR public.belongs_salon(salon_id)));
CREATE POLICY ticket_update ON public.tickets_suporte FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'super_admin')) WITH CHECK(public.has_role(auth.uid(),'super_admin'));
CREATE TABLE public.referral_sales (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.salons(id), reseller_id uuid NOT NULL, request_id uuid NOT NULL UNIQUE REFERENCES public.subscription_requests(id), buyer_name text NOT NULL DEFAULT '', amount numeric NOT NULL, applied_pct numeric NOT NULL DEFAULT 20, commission numeric NOT NULL, status text NOT NULL DEFAULT 'pendente_a_pagar', created_at timestamptz NOT NULL DEFAULT now(), paid_at timestamptz);
GRANT SELECT,UPDATE ON public.referral_sales TO authenticated; GRANT ALL ON public.referral_sales TO service_role;
ALTER TABLE public.referral_sales ENABLE ROW LEVEL SECURITY;
CREATE POLICY referral_read ON public.referral_sales FOR SELECT TO authenticated USING(reseller_id=auth.uid() OR public.manages_salon(salon_id));
CREATE POLICY referral_pay ON public.referral_sales FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'super_admin')) WITH CHECK(public.has_role(auth.uid(),'super_admin'));
CREATE TABLE public.referral_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.salons(id), sale_id uuid NOT NULL UNIQUE REFERENCES public.referral_sales(id), message text NOT NULL, read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.referral_notifications TO authenticated; GRANT ALL ON public.referral_notifications TO service_role;
ALTER TABLE public.referral_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notifications_read ON public.referral_notifications FOR SELECT TO authenticated USING(public.manages_salon(salon_id));
CREATE POLICY notifications_update ON public.referral_notifications FOR UPDATE TO authenticated USING(public.manages_salon(salon_id)) WITH CHECK(public.manages_salon(salon_id));
ALTER PUBLICATION supabase_realtime ADD TABLE public.referral_notifications, public.referral_sales;
CREATE TABLE public.memoria_ia (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.salons(id), conversation_id uuid NOT NULL, pergunta text NOT NULL, resposta text NOT NULL DEFAULT '', correcao_dona text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.memoria_ia TO authenticated; GRANT ALL ON public.memoria_ia TO service_role;
ALTER TABLE public.memoria_ia ENABLE ROW LEVEL SECURITY;
CREATE POLICY memory_manage ON public.memoria_ia FOR ALL TO authenticated USING(public.manages_salon(salon_id)) WITH CHECK(public.manages_salon(salon_id));
CREATE TABLE public.fila_mensagens_ia (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id uuid NOT NULL REFERENCES public.salons(id), client_id uuid REFERENCES public.salon_clients(id), appointment_id uuid REFERENCES public.appointments(id), dedupe_key text NOT NULL UNIQUE, cliente_whatsapp text NOT NULL, mensagem text NOT NULL, tipo text NOT NULL, status text NOT NULL DEFAULT 'pendente', agendado_para timestamptz NOT NULL, error text NOT NULL DEFAULT '', attempts integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.fila_mensagens_ia TO authenticated; GRANT ALL ON public.fila_mensagens_ia TO service_role;
ALTER TABLE public.fila_mensagens_ia ENABLE ROW LEVEL SECURITY;
CREATE POLICY queue_read ON public.fila_mensagens_ia FOR SELECT TO authenticated USING(public.manages_salon(salon_id));
CREATE FUNCTION public.confirm_subscription_sale() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _s public.salons; _r public.resellers; _id uuid; BEGIN
IF new.status='confirmado' AND old.status<>'confirmado' THEN
IF new.user_id IS NOT NULL THEN SELECT * INTO _s FROM public.salons WHERE owner_id=new.user_id LIMIT 1; ELSE SELECT s.* INTO _s FROM public.salons s JOIN public.profiles p ON p.id=s.owner_id WHERE lower(p.email)=lower(new.email) LIMIT 1; END IF;
IF _s.id IS NOT NULL THEN UPDATE public.salons SET status='ativo',plan_id=new.plan_id WHERE id=_s.id;
SELECT * INTO _r FROM public.resellers WHERE user_id=_s.reseller_id AND user_id<>_s.owner_id;
IF _r.user_id IS NOT NULL THEN INSERT INTO public.referral_sales(salon_id,reseller_id,request_id,buyer_name,amount,applied_pct,commission) VALUES(_s.id,_r.user_id,new.id,new.name,new.amount,_r.commission_pct,round(new.amount*_r.commission_pct/100,2)) ON CONFLICT(request_id) DO NOTHING RETURNING id INTO _id;
IF _id IS NOT NULL THEN INSERT INTO public.referral_notifications(salon_id,sale_id,message) VALUES(_s.id,_id,'🎉 Nova venda por indicação de '||coalesce((SELECT full_name FROM public.profiles WHERE id=_r.user_id),'')||'. Cliente: '||new.name||'. Comissão: R$ '||round(new.amount*_r.commission_pct/100,2)); END IF;
END IF; END IF; END IF; RETURN new; END $$;
CREATE TRIGGER confirmed_subscription AFTER UPDATE ON public.subscription_requests FOR EACH ROW EXECUTE FUNCTION public.confirm_subscription_sale();
CREATE FUNCTION public.become_reseller() RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _code text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na sua conta'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'revendedor') ON CONFLICT DO NOTHING; INSERT INTO public.resellers(user_id,code) VALUES(auth.uid(),upper(substr(replace(auth.uid()::text,'-',''),1,8))) ON CONFLICT(user_id) DO NOTHING; SELECT code INTO _code FROM public.resellers WHERE user_id=auth.uid(); RETURN _code; END $$;
REVOKE ALL ON FUNCTION public.become_reseller() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.become_reseller() TO authenticated;
CREATE FUNCTION public.validate_professional_commission() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF new.commission_pct<0 OR new.commission_pct>100 THEN RAISE EXCEPTION 'Comissão precisa ser entre 0 e 100'; END IF; RETURN new; END $$;
CREATE TRIGGER professional_commission BEFORE INSERT OR UPDATE ON public.professionals FOR EACH ROW EXECUTE FUNCTION public.validate_professional_commission();